GRIPPER_JOINT = 'finger_joint'
OBJECT_ID = 'u_brown'

def check(ctx):
    held = ctx.held_object()
    if held != OBJECT_ID:
        return None
    j = ctx.joint(GRIPPER_JOINT)
    if j is None or j.get('effort') is None:
        return None
    eff = abs(j['effort'])
    limit = ctx.value('max_clamp_effort')
    if eff > limit:
        return {'value': eff, 'detail': 'clamp effort on u_brown exceeded registry max_clamp_effort'}
    return None

TCP_FRAME = 'tcp'
OBJECT_ID = 'u_brown'

def check(ctx):
    held = ctx.held_object()
    if held != OBJECT_ID:
        ctx.state.pop('baseline', None)
        return None
    try:
        t = ctx.transform(TCP_FRAME, OBJECT_ID)
    except Exception:
        return None
    pos = t['translation']
    if 'baseline' not in ctx.state:
        ctx.state['baseline'] = pos
        return None
    base = ctx.state['baseline']
    d = ctx.dist(pos, base)
    tol = ctx.value('grasp_slip_tolerance_m')
    if d > tol:
        return {'value': d, 'detail': 'u_brown moved relative to the gripper while held (slip)'}
    return None

